-- Private illustrative covers, separate from published evidence and authorization snapshots.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values ('ridgewood-project-photos','ridgewood-project-photos',false,5242880,array['image/jpeg','image/png','image/webp'])
on conflict (id) do nothing;
create policy "project_cover_read" on storage.objects for select to authenticated using (bucket_id = 'ridgewood-project-photos' and exists (select 1 from public.project_states ps where ps.id::text = (storage.foldername(storage.objects.name))[1] and storage.objects.name = ps.id::text || '/cover' and public.is_workspace_member(ps.workspace_id)));
create policy "project_cover_insert" on storage.objects for insert to authenticated with check (bucket_id = 'ridgewood-project-photos' and exists (select 1 from public.project_states ps where ps.id::text = (storage.foldername(storage.objects.name))[1] and storage.objects.name = ps.id::text || '/cover' and public.is_workspace_member(ps.workspace_id) and ps.archived_at is null and ps.status = 'active' and public.has_app_permission(ps.workspace_id, 'document.create_draft')));
create policy "project_cover_update" on storage.objects for update to authenticated using (bucket_id = 'ridgewood-project-photos' and exists (select 1 from public.project_states ps where ps.id::text = (storage.foldername(storage.objects.name))[1] and storage.objects.name = ps.id::text || '/cover' and public.is_workspace_member(ps.workspace_id) and ps.archived_at is null and ps.status = 'active' and public.has_app_permission(ps.workspace_id, 'document.create_draft'))) with check (bucket_id = 'ridgewood-project-photos' and exists (select 1 from public.project_states ps where ps.id::text = (storage.foldername(storage.objects.name))[1] and storage.objects.name = ps.id::text || '/cover' and public.is_workspace_member(ps.workspace_id) and ps.archived_at is null and ps.status = 'active' and public.has_app_permission(ps.workspace_id, 'document.create_draft')));
create policy "project_cover_delete" on storage.objects for delete to authenticated using (bucket_id = 'ridgewood-project-photos' and exists (select 1 from public.project_states ps where ps.id::text = (storage.foldername(storage.objects.name))[1] and storage.objects.name = ps.id::text || '/cover' and public.is_workspace_member(ps.workspace_id) and ps.archived_at is null and ps.status = 'active' and public.has_app_permission(ps.workspace_id, 'document.create_draft')));
